"""Interpretable component scoring functions."""
from decimal import Decimal
from typing import Any
from integrity_engine.schemas.integrity import IntegrityComponent, IntegrityEvidence

WEIGHTS={"Cross-Venue Confirmation":Decimal("0.25"),"Spot Participation":Decimal("0.20"),"Liquidity Stability":Decimal("0.20"),"Volume Quality":Decimal("0.15"),"Derivatives Dependence":Decimal("0.15"),"Liquidation Dependence":Decimal("0.05")}
D=Decimal
def ev(source,metric,current,interpretation,window=None,quality=None,effect=None):return IntegrityEvidence(source=source,metric=metric,current_value=current,window=window,data_quality=quality or [],interpretation=interpretation,effect=effect or "input_to_component_score")
def component(name,score,confidence,status,evidence,flags=None,availability="available"):
    bounded = None if score is None else max(D(0),min(D(100),D(score)))
    return IntegrityComponent(name=name,score=bounded,confidence=max(D(0),min(D(1),D(confidence))),weight=WEIGHTS[name],status=status,availability=availability,evidence=evidence,data_quality_flags=flags or [])

def cross(cross):
    if cross is None or not cross.active_venues or cross.confirmation_ratio is None:return component("Cross-Venue Confirmation",None,D("0"),"insufficient_data",[],["missing_cross_venue_metrics"],"unavailable")
    ratio=cross.confirmation_ratio; active=len(cross.active_venues); dispersion=cross.dispersion_bps or D(0); score=(ratio*D(100) if ratio is not None else D(50)); score=max(D(0),score-max(D(0),dispersion-D(2))*D(5)); conf=min(D(1),D(active)/D(5))*(D("0.5") if cross.data_quality_flags or cross.dispersion_bps is None else D(1)); return component("Cross-Venue Confirmation",score,conf,cross.confirmation_state,[ev("market.metrics.cross_venue","confirmation_ratio",ratio,"venue directional agreement",cross.window,cross.data_quality_flags),ev("market.metrics.cross_venue","dispersion_bps",dispersion,"cross-venue price dispersion",cross.window)],cross.data_quality_flags,"partial" if cross.data_quality_flags or cross.dispersion_bps is None else "available")
def spot(metrics,cross=None,deriv=None):
    if metrics is None or metrics.trade_count <= 0 or metrics.quote_volume is None or metrics.quote_volume <= 0 or "no_trades_in_window" in metrics.data_quality_flags:return component("Spot Participation",None,D("0"),"insufficient_data",[],["missing_spot_metrics"],"unavailable")
    ratio=getattr(metrics,"perpetual_to_spot_volume_ratio",None) if hasattr(metrics,"perpetual_to_spot_volume_ratio") else getattr(deriv,"perpetual_to_spot_volume_ratio",None) if deriv is not None else None
    score=D(75) if ratio is None else max(D(10),D(100)-max(D(0),ratio-D(1))*D(12)); q=getattr(metrics,"quote_volume",None); conf=D("0.8") if q is not None else D("0.4");return component("Spot Participation",score,conf,"strong" if score>=80 else "moderate" if score>=55 else "weak",[ev("market.metrics","quote_volume",q,"spot quote participation",metrics.window,getattr(metrics,"data_quality_flags",[]))],getattr(metrics,"data_quality_flags",[]))
def liquidity(metrics):
    if metrics is None or (metrics.spread_bps is None and metrics.depth_change is None) or "insufficient_orderbook_samples" in metrics.data_quality_flags:return component("Liquidity Stability",None,D("0"),"insufficient_data",[],["missing_market_metrics"],"unavailable")
    spread=metrics.spread_bps or D(0); depth=metrics.depth_change or D(0); score=max(D(0),D(100)-spread*D(10)-max(D(0),-depth)*D(100));flags=list(metrics.data_quality_flags);stale="stale_orderbook" in flags or metrics.spread_bps is None or metrics.depth_change is None;conf=D("0.4") if stale else D("0.9");return component("Liquidity Stability",score,conf,"stable" if score>=75 else "deteriorating" if score>=45 else "stressed",[ev("market.metrics","spread_bps",spread,"quoted spread stability",metrics.window,flags),ev("market.metrics","depth_change",depth,"depth change",metrics.window,flags)],flags,"partial" if stale else "available")
def volume(metrics,cross=None):
    if cross is None or cross.largest_venue_volume_share is None or not cross.venue_volume_shares or not cross.active_venues or sum(cross.venue_quote_volumes.values(),D(0))<=0:return component("Volume Quality",None,D("0"),"insufficient_data",[],["missing_cross_venue_metrics"],"unavailable")
    concentration=cross.largest_venue_volume_share or D(0);score=max(D(0),D(100)-max(D(0),concentration-D("0.4"))*D(150));return component("Volume Quality",score,D("0.9") if cross.data_complete else D("0.5"),"broad" if score>=75 else "concentrated",[ev("market.metrics.cross_venue","largest_venue_volume_share",concentration,"venue volume concentration",cross.window)],cross.data_quality_flags,"partial" if not cross.data_complete or cross.data_quality_flags else "available")
def derivatives(deriv):
    if deriv is None or deriv.perpetual_to_spot_volume_ratio is None or any(f in deriv.data_quality_flags for f in ("stale_spot_reference","stale_perpetual_price","insufficient_window_history")):return component("Derivatives Dependence",None,D("0"),"insufficient_data",[],["missing_derivatives_metrics"],"unavailable")
    ratio=deriv.perpetual_to_spot_volume_ratio;score=D(75) if ratio is None else max(D(5),D(100)-max(D(0),ratio-D(1))*D(10));flags=list(deriv.data_quality_flags);available=sum(x is not None for x in (deriv.open_interest,deriv.funding_rate,deriv.basis_bps));conf=D("0.35")+D("0.15")*available;return component("Derivatives Dependence",score,conf,"balanced" if score>=70 else "elevated_dependence" if score>=40 else "high_dependence",[ev("market.metrics.derivatives","perpetual_to_spot_volume_ratio",ratio,"perpetual participation relative to spot",deriv.window,flags),ev("market.metrics.derivatives","basis_bps",deriv.basis_bps,"perpetual spot basis",deriv.window,flags)],flags,"partial" if available < 2 or flags else "available")
def liquidation(deriv):
    if deriv is None:return component("Liquidation Dependence",None,D("0"),"insufficient_data",[],["missing_derivatives_metrics"],"unavailable")
    volume=deriv.liquidation_quote_volume;quote=deriv.perpetual_quote_volume;flags=list(deriv.data_quality_flags)
    if volume is None or quote is None or quote<=0:return component("Liquidation Dependence",None,D("0"),"insufficient_data",[ev("market.metrics.derivatives","liquidation_quote_volume",None,"comparable liquidation notional unavailable",deriv.window,flags)],flags+["liquidation_feed_unavailable"],"unavailable")
    share=volume/quote if quote else D(0);score=max(D(0),D(100)-share*D(500));return component("Liquidation Dependence",score,D("0.85"),"low" if score>=70 else "elevated",[ev("market.metrics.derivatives","total_liquidation_volume",volume,"liquidation volume relative to perpetual volume",deriv.window,flags)],flags)
